#include <stdio.h>
#include <limits.h>

#define MAXN 101
#define INF 1000000000

int main() {
    int N, M;
    int graph[MAXN][MAXN];
    int dist[MAXN];
    int visited[MAXN];

    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            graph[i][j] = INF;
        }
        graph[i][i] = 0;
    }

    for (int i = 0; i < M; i++) {
        int A, B, C;
        scanf("%d %d %d", &A, &B, &C);
        if (C < graph[A][B]) {
            graph[A][B] = C;
            graph[B][A] = C;
        }
    }

    for (int i = 1; i <= N; i++) {
        dist[i] = INF;
        visited[i] = 0;
    }
    dist[1] = 0;

    for (int count = 0; count < N; count++) {
        int u = -1;
        int min = INF;

        for (int i = 1; i <= N; i++) {
            if (!visited[i] && dist[i] < min) {
                min = dist[i];
                u = i;
            }
        }

        if (u == -1) break;
        visited[u] = 1;

        for (int v = 1; v <= N; v++) {
            if (!visited[v] && graph[u][v] < INF) {
                if (dist[u] + graph[u][v] < dist[v]) {
                    dist[v] = dist[u] + graph[u][v];
                }
            }
        }
    }

    printf("%d\n", dist[N]);
    return 0;
}
